  check("the unblinding the finish hangs on, by hand: a^-1 times the double-blinded point for a shared entry is exactly the oracle's b times H(that entry), and that point opens exactly that entry's note", (await (async () => { const made = await app.psiRequestFor(psiAliceText, psiA); const reply = await app.psiPayloadAnswerFor(made.request, psiBobText, psiPayloadText, psiB); const p = app.parsePsiPayloadReply(reply); if (p === null) return false; const N = BigInt("0xffffffff00000000ffffffffffffffffbce6faada7179e84f3b9cac2fc632551"); let exp = N - 2n, inv = 1n, base = BigInt("0x" + psiA); while (exp > 0n) { if ((exp & 1n) === 1n) inv = inv * base % N; base = base * base % N; exp >>= 1n; } const unblinded = app.psiBlindPointHex(inv.toString(16).padStart(64, "0"), p.doublePoints[1]); if (unblinded === null || unblinded !== psiBlindOracle(psiB, "bob")) return false; let opened = null; for (const blob of p.payloadBlobs) { const v = await app.openPsiPayload(unblinded, blob); if (v !== null) opened = v; } return opened === "bring the blue folder"; })()));
