  check("a disjoint payload exchange finishes to an empty list — a real answer, not null — a stranger's scalar finishes empty too, and a tampered note is skipped while its honest neighbour still arrives", (await (async () => { const made = await app.psiRequestFor(psiAliceText, psiA); const disjoint = await app.psiPayloadAnswerFor(made.request, "xenia\nyuri", "xenia's note\nyuri's note", psiB); const none = await app.psiPayloadsFor(psiA, psiAliceText, disjoint); if (none === null || none.length !== 0) return false; const reply = await app.psiPayloadAnswerFor(made.request, psiBobText, psiPayloadText, psiB); const stranger = await app.psiPayloadsFor("cc".repeat(32), psiAliceText, reply); if (stranger === null || stranger.length !== 0) return false; const p = app.parsePsiPayloadReply(reply); const blobs = p.payloadBlobs.slice(); const bobBlob = psiPayloadOracle(psiBlindOracle(psiB, "bob"), "bring the blue folder"); const bi = blobs.indexOf(bobBlob); if (bi < 0) return false; const at = app.PSI_PAYLOAD_MAC_HEX + 2; blobs[bi] = blobs[bi].slice(0, at) + (blobs[bi][at] === "0" ? "1" : "0") + blobs[bi].slice(at + 1); const partial = await app.psiPayloadsFor(psiA, psiAliceText, app.formatPsiPayloadReply(p.doublePoints, blobs)); return partial !== null && partial.length === 1 && partial[0].item === "carol danvers"; })()));
  check("psiPayloadsFor and finishPsiPayloads refuse what they cannot judge as null: a reply answering fewer entries than the list names, a tool-47 reply, a junk reply, a zero scalar, a junk state and non-strings throughout", (await (async () => { const made = await app.psiRequestFor(psiAliceText, psiA); const reply = await app.psiPayloadAnswerFor(made.request, psiBobText, psiPayloadText, psiB); const short = await app.psiRequestFor("alice\nbob", psiA); const shortReply = await app.psiPayloadAnswerFor(short.request, psiBobText, psiPayloadText, psiB); const reply47 = await app.psiAnswerFor(made.request, psiBobText, psiB); return await app.psiPayloadsFor(psiA, psiAliceText, shortReply) === null && await app.psiPayloadsFor(psiA, psiAliceText, reply47) === null && await app.psiPayloadsFor(psiA, psiAliceText, "junk") === null && await app.psiPayloadsFor("00".repeat(32), psiAliceText, reply) === null && await app.psiPayloadsFor(null, psiAliceText, reply) === null && await app.psiPayloadsFor(psiA, null, reply) === null && await app.psiPayloadsFor(psiA, psiAliceText, null) === null && await app.finishPsiPayloads("junk", psiAliceText, reply) === null && await app.finishPsiPayloads(made.state, psiAliceText, "junk") === null && await app.finishPsiPayloads(null, null, null) === null; })()));
