  check("the failure the finish CAN catch: a 2-ballot among three pushes the hidden total to 4 of 3, and openTally fails closed as null rather than reporting it", (() => { const r = tallyRs[1]; const a = ptMul(BigInt("0x" + r), P4A_G); const b = ptAdd(ptMul(2n, P4A_G), ptMul(BigInt("0x" + r), tallyY)); const cheat = app.formatTallyBallot(tallyPointHex(a), tallyPointHex(b)); if (cheat === null) return false; const pile = [app.tallyBallotFor(1, tallyKey, tallyRs[0]), cheat, app.tallyBallotFor(1, tallyKey, tallyRs[2])].join("\n"); return app.openTally(tallyState, app.tallyBallotsFor(pile)) === null; })());
