  const bpBallot1 = app.tallyBallotFor(1, tallyKey, bpR);
  const bpProof0 = await app.proveBallot(bpBallot0, tallyKey, "0", bpR);
  const bpProof1 = await app.proveBallot(bpBallot1, tallyKey, "1", bpR);
